    }
    else if (votos == 567) {  
     mensagem = "Voto computado para PEDÃO";
     pedao = pedao + 1;
    }
    else if (votos == 478) { 
     mensagem = "Voto computado para EDGAR";
     edgar = edgar + 1;
    }

    else if (votos == 0) { 
