              "\nVotos para EDGAR.............: = "+edgar +
              "\nVotos em BRANCO............: = "+branco +
              "\nVotos NULO.........................: = "+nulo +
              "\n\n-PERCENTUAL DE VOTOS VÁLIDOS-"+
              "\n\nJOSEFINO.............................: = "+ josefinoPercentual + "%"+
              "\nPEDÃO...................................: = "+ pedaoPercentual +  "%"+
